using namespace ts;using namespace ts::playback;using namespace ts::prototype;
thread_local bool callback=false;std::atomic<unsigned> allocations{0};
void* operator new(std::size_t n){if(callback)++allocations;if(auto p=std::malloc(n?n:1))return p;throw std::bad_alloc();}void* operator new[](std::size_t n){return ::operator new(n);}void operator delete(void* p)noexcept{std::free(p);}void operator delete[](void* p)noexcept{std::free(p);}
void check(bool b,const char* message){if(!b)throw std::runtime_error(message);}
SeekSnapshot wait(PlaybackEngine& e,std::uint64_t id){auto end=std::chrono::steady_clock::now()+std::chrono::seconds(20);for(;;){auto s=e.getSeekSnapshot();if(s.id==id&&s.status!=SeekStatus::Pending&&s.status!=SeekStatus::Preparing){check(s.readyNs>=s.observedNs&&s.observedNs>0,"seek timestamp ordering");return s;}if(std::chrono::steady_clock::now()>end)throw std::runtime_error("seek timeout: "+std::string(name(s.status))+" id="+std::to_string(id)+" output="+std::to_string(s.outputFrame));std::this_thread::sleep_for(std::chrono::milliseconds(1));}}
std::vector<float> drain(PlaybackEngine& e){std::array<std::array<float,4096>,2> b{};float* p[]={b[0].data(),b[1].data()};std::vector<float> result;std::size_t count=0;while(e.getPlaybackState()==PlaybackState::Playing){auto n=std::min<std::size_t>(std::array<std::size_t,5>{64,128,256,512,4096}[count++%5],e.getPlaybackDiagnostics().fifoAvailable);if(!n){std::this_thread::sleep_for(std::chrono::microseconds(100));continue;}callback=true;auto r=e.renderAudio(p,n,1);callback=false;for(std::size_t i=0;i<r.received;++i)for(std::size_t c=0;c<e.channels();++c)result.push_back(p[c][i]);}check(e.getPlaybackState()==PlaybackState::Ended,"EOS");check(e.getPlaybackDiagnostics().missingFrames==0,"supply");return result;}
StretchConfig config(std::uint32_t rate,unsigned channels,double speed){StretchConfig c;c.sampleRate=rate;c.channels=channels;c.timeRatio=1/speed;c.enableMultiResolution=true;c.qualityMode=QualityMode::Experimental;c.enablePhaseLocking=true;c.enableTransientHandling=true;c.enableAdaptiveTimeMapping=true;c.enablePreciseTransientAnchoring=true;c.enableStereoCoherence=true;return c;}
int main(){auto dir=std::filesystem::temp_directory_path()/("phase54_seek_"+std::to_string(getpid()));try{std::filesystem::create_directory(dir);unsigned compared=0;double maxPrepare=0;
 for(auto [rate,channels]:{std::pair<unsigned,unsigned>{44100,1},{44100,2},{48000,1},{48000,2}}){AudioBuffer a;a.sampleRate=rate;a.channels.resize(channels,std::vector<float>(rate*2));for(std::size_t i=0;i<a.channels[0].size();++i)for(unsigned c=0;c<channels;++c){a.channels[c][i]=.1f*std::sin(2*3.141592653589793*437.3*i/rate+c*.3);if(i%11025==0)a.channels[c][i]+=.5f;}auto path=dir/(std::to_string(rate)+".wav");WavWriter::write(path,a);auto cache=std::make_shared<PlaybackAnalysisCache>();
 for(double speed:{.4,.5,1.,1.5,2.}){auto c=config(rate,channels,speed);auto detector=c;detector.timeRatio=2;auto analysis=Phase13StreamingEngine(detector).analyzeTransientEvents(path);Phase39TimeMap timeline(analysis,rate,Phase39Speed::fromDouble(speed),Phase39Planning::L2);auto total=std::llround(a.channels[0].size()/speed);std::vector<float> reference;
 Phase35TransitionEngine(c).processWav(path,{},timeline.current(),{},total,16384,nullptr,[&](const float*const* p,std::size_t n){for(std::size_t i=0;i<n;++i)for(unsigned ch=0;ch<channels;++ch)reference.push_back(p[ch][i]);});
 for(auto preset:{Preset::Candidate,Preset::Baseline})for(double seconds:{0.,.71,1.97,2.}){std::cerr<<"case "<<rate<<" "<<speed<<" "<<int(preset)<<" "<<seconds<<std::endl;PlaybackEngine e;auto cfg=preset==Preset::Candidate?Configuration::candidate(speed):Configuration::baseline(speed);cfg.analysisCache=cache;cfg.verifyRawPcm=true;check(e.prepare(path,cfg),"prepare");auto s=wait(e,e.seekToInputSeconds(seconds));check(s.status==SeekStatus::Completed,"seek completion");maxPrepare=std::max(maxPrepare,double(s.readyNs-s.observedNs)*1e-9);check(e.getStartupDiagnostics().analysisHit,"seek reused analysis");check(e.play(),"play seek suffix");auto got=drain(e);std::vector<float> expected(reference.begin()+s.outputFrame*channels,reference.end());check(got==expected,"independent Phase35 suffix all-sample equality");check(e.getPlaybackDiagnostics().outputStartFrame==s.outputFrame,"mapped seek origin");++compared;}
 }
 PlaybackEngine e;auto cfg=Configuration::candidate(.4);cfg.analysisCache=cache;check(e.prepare(path,cfg)&&e.play()&&e.pause(),"paused seek setup");auto s=wait(e,e.seekToInputSeconds(.7));check(s.status==SeekStatus::Completed&&e.getPlaybackState()==PlaybackState::Paused,"paused remains paused");std::array<std::array<float,512>,2>b{};float* p[]={b[0].data(),b[1].data()};auto position=e.getCurrentPlaybackPosition();callback=true;auto r=e.renderAudio(p,512,1);callback=false;check(r.received==0&&e.getCurrentPlaybackPosition().outputFrame==position.outputFrame,"paused seek FIFO preserved");check(e.resume(),"resume after seek");drain(e);
 e.stop();check(e.prepare(path,cfg)&&e.play(),"playing seek");auto oldSession=e.getPlaybackDiagnostics().session;auto id=e.seekToInputSeconds(1.3);s=wait(e,id);check(s.status==SeekStatus::Completed&&e.getPlaybackState()==PlaybackState::Playing&&e.getPlaybackDiagnostics().session>oldSession,"playing handoff");e.setSpeed(2);drain(e);
 e.stop();check(e.prepare(path,cfg),"latest fixture");auto first=e.seekToInputSeconds(1.9);auto second=e.seekToInputSeconds(.7);auto last=e.seekToInputSeconds(.1);s=wait(e,last);check(s.status==SeekStatus::Completed&&s.requestedInputFrame==std::uint64_t(std::llround(.1*rate)),"latest seek wins");auto history=e.seekHistory();for(auto superseded:{first,second})check(std::any_of(history.begin(),history.end(),[&](auto& x){return x.id==superseded&&x.status==SeekStatus::Replaced;}),"replaced seek recorded");
 auto cancel=e.seekToInputSeconds(1.9);e.stop();std::this_thread::sleep_for(std::chrono::milliseconds(50));check(e.getPlaybackState()==PlaybackState::Stopped&&e.getSeekSnapshot().id==cancel&&e.getSeekSnapshot().status==SeekStatus::Cancelled,"stop cancellation no stale publish");
 check(e.prepare(path,cfg),"route fixture");cancel=e.seekToInputSeconds(1.9);e.stop(StopReason::RouteChanged);std::this_thread::sleep_for(std::chrono::milliseconds(50));check(e.getPlaybackDiagnostics().reason==StopReason::RouteChanged&&e.getSeekSnapshot().status==SeekStatus::Cancelled,"route cancellation");
 check(e.prepare(path,cfg),"speed during seek");id=e.seekToInputSeconds(1.5);e.setSpeed(1.5);s=wait(e,id);check(s.status==SeekStatus::Completed&&s.initialSpeed==1.5&&e.getAppliedTargetSpeed()==1.5,"latest speed becomes seek initial speed");
 auto valid=e.seekToInputSeconds(1.9);auto invalid=e.seekToInputFrame(rate*3);
 for(unsigned tries=0;tries<20000;++tries){auto h=e.seekHistory();if(std::any_of(h.begin(),h.end(),[&](auto& s){return s.id==valid;}))break;std::this_thread::sleep_for(std::chrono::milliseconds(1));}check(e.getSeekSnapshot().id==invalid&&e.getSeekSnapshot().status==SeekStatus::Rejected,"older completion cannot overwrite latest rejected snapshot");
 auto finalHistory=e.seekHistory();check(std::any_of(finalHistory.begin(),finalHistory.end(),[&](auto& s){return s.id==valid;}),"prior valid request terminated");
 auto rejected=e.seekToInputFrame(rate*3);check(e.getSeekSnapshot().id==rejected&&e.getSeekSnapshot().status==SeekStatus::Rejected,"out of range");for(double bad:{-.1,std::numeric_limits<double>::quiet_NaN(),std::numeric_limits<double>::infinity()}){bool rejected=false;try{e.seekToInputSeconds(bad);}catch(...){rejected=true;}check(rejected,"invalid seconds");}
 e.stop();cfg=Configuration::candidate(.5);cfg.reuseAnalysis=false;cfg.verifyRawPcm=true;
 check(e.prepare(path,cfg),"cache disabled fixture");s=wait(e,e.seekToInputSeconds(.7));check(s.status==SeekStatus::Completed&&!e.getStartupDiagnostics().analysisHit,"cache disabled seek");
 check(e.play(),"cache disabled suffix play");drain(e);auto d=e.getPlaybackDiagnostics();
 check(e.rawPcmSha()==verification::referenceHash(path,.5,Preset::Candidate,{},d.outputStartFrame,d.producedFrames),"cache disabled independent suffix");
 }
 check(allocations==0,"callback C++ allocations");std::filesystem::remove_all(dir);std::cout<<"Phase35 suffix comparisons="<<compared<<" max_seek_seconds="<<maxPrepare<<" callback_allocations="<<allocations<<"; Latest-Wins/playing/paused/stop/route/speed/EOS PASS\n";return 0;
}catch(const std::exception&e){std::filesystem::remove_all(dir);std::cerr<<e.what()<<'\n';return 1;}}
